def apply_reset(request, resets, users, now):
    token = request.get('token')
    if not isinstance(token, str) or not token:
        return False
    record = resets.get(token)
    if not record or record['expires_at'] <= now or record['used']:
        return False
    account = record['account']
    if request.get('account', account) != account:
        return False
    if account not in users:
        return False
    replacement = request.get('new_hash')
    if not isinstance(replacement, str) or len(replacement) < 16:
        return False
    users[account]['login_hash'] = replacement
    record['used'] = True
    return True


def issue_reset(account, token, expires_at):
    if not account or not token:
        raise ValueError('Account and token are required')
    return {'account': account, 'expires_at': expires_at, 'used': False}

